<script lang="ts">import type { Rating } from '../../api/types';let { onrate,disabled=false }=$props<{onrate:(r:Rating)=>void;disabled?:boolean}>();const ratings:[Rating,string,string][]=[['again','Again','1'],['hard','Hard','2'],['good','Good','3'],['easy','Easy','4']];</script><div class="ratings">{#each ratings as [value,label,key]}<button class={value} {disabled} onclick={()=>onrate(value)}><kbd>{key}</kbd><span>{label}</span></button>{/each}</div>
<style>.ratings{display:grid;grid-template-columns:repeat(4,minmax(90px,145px));justify-content:center;gap:9px}.ratings button{height:45px;display:flex;align-items:center;justify-content:center;gap:10px;border:1px solid var(--border);border-top:2px solid var(--rating);background:var(--surface-1);color:var(--text-secondary);border-radius:8px;box-shadow:var(--shadow-sm);transition:transform var(--motion-fast) var(--ease),box-shadow var(--motion-fast),background var(--motion-fast)}.ratings button:hover{transform:translateY(-2px);background:var(--surface-hover);color:var(--text-primary);box-shadow:var(--shadow-lg)}kbd{display:grid;place-items:center;width:19px;height:19px;border:1px solid var(--border-strong);border-radius:4px;font:10px inherit;color:var(--text-muted)}.again{--rating:#d95a67}.hard{--rating:#d39542}.good{--rating:#4f92dc}.easy{--rating:#3ca677}</style>
